'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  Camera,
  Cloud,
  Edit3,
  ExternalLink,
  Heart,
  ImagePlus,
  Link2,
  LockKeyhole,
  Music2,
  Pause,
  Play,
  Quote,
  Sparkles,
  Sun,
  ThermometerSnowflake,
  Upload,
  Volume2,
  VolumeX,
  Wind,
  X,
} from 'lucide-react'

const moods = [
  { label: 'Días soleados', icon: Sun, note: 'Para cuando el mundo se ilumina contigo.', color: 'gold' },
  { label: 'Días fríos', icon: ThermometerSnowflake, note: 'Un abrazo escrito para abrigarte.', color: 'ice' },
  { label: 'Cuando estés triste', icon: Cloud, note: 'Recuerda: nunca estás sola en esto.', color: 'lavender' },
  { label: 'Cuando estés feliz', icon: Sparkles, note: 'Que tu sonrisa se quede un rato más.', color: 'mint' },
]

const defaultPhotos = [
  { src: '/romantic-memory-cover.png', caption: 'Donde todo comenzó' },
  { src: '/romantic-memory-cover.png', caption: 'Un instante para guardar' },
  { src: '/romantic-memory-cover.png', caption: 'Tú, siempre tú' },
]

export default function Page() {
  const [activePage, setActivePage] = useState(0)
  const [isPlaying, setIsPlaying] = useState(false)
  const [soundOn, setSoundOn] = useState(true)
  const [isEditing, setIsEditing] = useState(false)
  const [message, setMessage] = useState('Desde que llegaste, los días tienen otra luz.\n\nGracias por cada risa, cada conversación y cada pequeño momento que se vuelve enorme cuando es contigo.\n\nEste rincón es para guardar todo lo que siento por ti, sin prisa y para siempre.')
  const [photos, setPhotos] = useState(defaultPhotos)
  const fileInput = useRef<HTMLInputElement>(null)

  const next = () => setActivePage((page) => Math.min(page + 1, 3))
  const previous = () => setActivePage((page) => Math.max(page - 1, 0))

  useEffect(() => {
    const handler = (event: WheelEvent) => {
      if (Math.abs(event.deltaY) < 20) return
      if (event.deltaY > 0) next()
      else previous()
    }
    window.addEventListener('wheel', handler, { passive: true })
    return () => window.removeEventListener('wheel', handler)
  }, [])

  const progress = useMemo(() => `${(activePage / 3) * 100}%`, [activePage])

  const handleFiles = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files ?? []).filter((file) => file.type.startsWith('image/'))
    const nextPhotos = files.map((file) => ({ src: URL.createObjectURL(file), caption: file.name.replace(/\.[^/.]+$/, '') }))
    setPhotos((current) => [...current, ...nextPhotos])
  }

  return (
    <main className="memory-app">
      <div className="grain" aria-hidden="true" />
      <header className="topbar">
        <a className="brand" href="#inicio" onClick={() => setActivePage(0)}>
          <span className="brand-mark"><Heart fill="currentColor" /></span>
          <span><strong>bloc de recuerdos</strong><small>un lugar para nostruuuus</small></span>
        </a>
        <div className="top-actions">
          <button className="icon-button" aria-label={soundOn ? 'Silenciar sonidos' : 'Activar sonidos'} onClick={() => setSoundOn(!soundOn)}>
            {soundOn ? <Volume2 /> : <VolumeX />}
          </button>
          <button className="edit-button" onClick={() => setIsEditing(!isEditing)}><Edit3 /> {isEditing ? 'Guardar cambios' : 'Editar bloc'}</button>
        </div>
      </header>

      <div className="stage" id="inicio">
        <aside className="side-note left-note"><span>para ti, con cariño</span><i /></aside>
        <div className="page-count"><span>0{activePage + 1}</span><i />04</div>

        <section className={`memory-page page-${activePage}`} aria-live="polite">
          {activePage === 0 && (
            <div className="welcome-page">
              <div className="eyebrow"><span className="dot" /> capítulo uno · el comienzo</div>
              <div className="welcome-grid">
                <div className="welcome-copy">
                  <p className="script">para la persona que hace hogar en mi corazón</p>
                  <h1>Hola,<br /><em>mi sai.</em></h1>
                  {isEditing ? <textarea className="message-editor" value={message} onChange={(e) => setMessage(e.target.value)} aria-label="Mensaje de bienvenida editable" /> : <div className="message-copy">{message.split('\n').map((line, index) => line ? <p key={index}>{line}</p> : <br key={index} />)}</div>}
                  <div className="signature"><span>Con todo mi cariñooo,</span><strong>Siempre tuyo ñeeeeee</strong></div>
                </div>
                <div className="cover-wrap">
                  <div className="photo-frame"><img src="/romantic-memory-cover.png" alt="Dos siluetas tomadas de la mano durante un atardecer" /><span className="photo-caption">nuestro primer capítulo</span></div>
                  <div className="stamp"><Heart fill="currentColor" /><span>hecho<br />para ti</span></div>
                </div>
              </div>
              <button className="continue-button" onClick={next}>seguir leyendo <ArrowDown /></button>
            </div>
          )}

          {activePage === 1 && (
            <div className="music-page">
              <div className="eyebrow"><span className="dot" /> capítulo dos · nuestra banda sonora</div>
              <div className="music-layout">
                <div className="record-art"><div className="record"><div className="record-label"><Heart fill="currentColor" /><span>tú + yo</span></div></div><div className="record-shadow" /></div>
                <div className="music-copy"><p className="script">si tuviera que elegir una canción</p><h2>Lo que siento<br /><em>por ti.</em></h2><p className="muted-copy">Hay canciones que no se escuchan, se sienten. Esta me recuerda a nosotros.</p><div className="track"><div className="track-icon"><Music2 /></div><div className="track-info"><strong>La canción que me lleva a ti</strong><span>nuestra playlist · favorita</span></div><button className="play-button" onClick={() => setIsPlaying(!isPlaying)} aria-label={isPlaying ? 'Pausar canción' : 'Reproducir canción'}>{isPlaying ? <Pause fill="currentColor" /> : <Play fill="currentColor" />}</button></div><a className="song-link" href="https://www.youtube.com/results?search_query=cancion+de+amor" target="_blank" rel="noreferrer"><Link2 /> abrir en YouTube <ExternalLink /></a></div>
              </div>
            </div>
          )}

          {activePage === 2 && (
            <div className="moods-page"><div className="eyebrow"><span className="dot" /> capítulo tres · para cada versión de ti</div><div className="moods-heading"><div><p className="script">abre cuando lo necesites</p><h2>Para tus<br /><em>días.</em></h2></div><Quote className="quote-icon" /></div><div className="mood-grid">{moods.map(({ label, icon: Icon, note, color }) => <button key={label} className={`mood-card ${color}`} onClick={() => alert(note)}><span className="mood-icon"><Icon /></span><span className="mood-label">{label}</span><span className="mood-arrow">↗</span></button>)}</div></div>
          )}

          {activePage === 3 && (
            <div className="photos-page"><div className="eyebrow"><span className="dot" /> capítulo cuatro · momentos que guardamos</div><div className="photos-heading"><div><p className="script">una pequeña colección de nosotros</p><h2>Nuestras<br /><em>fotos.</em></h2></div><button className="upload-button" onClick={() => fileInput.current?.click()}><Upload /> subir fotos</button><input ref={fileInput} type="file" accept="image/*" multiple hidden onChange={handleFiles} /></div><div className="photos-grid">{photos.map((photo, index) => <figure key={`${photo.src}-${index}`} className={`photo-card photo-${index % 3}`}><img src={photo.src} alt={photo.caption} /><figcaption>{photo.caption}</figcaption></figure>)}<button className="drive-card" onClick={() => fileInput.current?.click()}><ImagePlus /><strong>Añadir un recuerdo</strong><span>o sincronizar carpeta de Drive</span></button></div><div className="drive-status"><Cloud /><span><strong>Carpeta compartida</strong> · tus fotos aparecerán aquí en tiempo real</span><span className="live-dot">en vivo</span></div></div>
          )}
        </section>

        <button className="nav-arrow prev" onClick={previous} disabled={activePage === 0} aria-label="Página anterior"><ArrowLeft /></button>
        <button className="nav-arrow next" onClick={next} disabled={activePage === 3} aria-label="Página siguiente"><ArrowRight /></button>
      </div>
      <footer className="footer"><span>hecho con intención</span><div className="progress"><i style={{ width: progress }} /></div><span>{activePage + 1} / 4</span></footer>
    </main>
  )
}
